import { BRAAK_STAGE } from '../disease/staging';
import type { ScenarioId } from '../disease/scenarios';
import { SCENARIOS } from '../disease/scenarios';
import art from './brainArt.json';

export type RegionId = 'frontal' | 'parietal' | 'temporal' | 'occipital' | 'cerebellum' | 'brainstem' | 'hippocampus';

export interface Region {
  id: RegionId;
  path: string;
  label: { x: number; y: number };
  tint: string;
  strong: string;
}

export interface TauBlob {
  x: number;
  y: number;
  r: number;
  at: number;
}

/**
 * Left lateral brain generated by the pipeline (neurosim_data/art.py) from the real fsaverage5
 * cortex, front to the left: the silhouette, the four lobes, the deepest visible sulci, the
 * hippocampus and brainstem from the atlas volume, and a 2D anchor per cortical parcel. Tints are
 * light steps of the validated categorical hues; every region also carries a text label, so colour
 * is never the only cue.
 */
export const SILHOUETTE: string = art.silhouette;
export const SULCI: string[] = art.sulci;

const COLORS: Record<RegionId, { tint: string; strong: string }> = {
  frontal: { tint: '#d6e5f8', strong: '#2a78d6' },
  parietal: { tint: '#cfeee2', strong: '#1baf7a' },
  occipital: { tint: '#fcebc2', strong: '#eda100' },
  temporal: { tint: '#e2ddf8', strong: '#6250d6' },
  cerebellum: { tint: '#f8dfe9', strong: '#e87ba4' },
  brainstem: { tint: '#eae6e0', strong: '#b0a99e' },
  hippocampus: { tint: '#fbd9c5', strong: '#eb6834' },
};

const cb = art.cerebellum.bbox;
const stemLabel = { x: art.brainstem.label[0] + 32, y: Math.min(art.brainstem.label[1] - 4, 286) };

export const REGIONS: Region[] = [
  { id: 'brainstem', path: art.brainstem.path, label: stemLabel, ...COLORS.brainstem },
  {
    id: 'cerebellum',
    path: art.cerebellum.path,
    label: { x: (cb[0] + cb[2]) / 2 + 30, y: (cb[1] + cb[3]) / 2 + 34 },
    ...COLORS.cerebellum,
  },
  ...art.lobes.map(l => ({
    id: l.id as RegionId,
    path: l.path,
    label: { x: l.label[0], y: l.label[1] },
    ...COLORS[l.id as RegionId],
  })),
];

export const HIPPO_ANCHOR = { x: art.hippocampus.label[0], y: art.hippocampus.label[1] };

export const HIPPOCAMPUS: Region = {
  id: 'hippocampus',
  path: art.hippocampus.path,
  label: { x: Math.max(70, HIPPO_ANCHOR.x - 92), y: 256 },
  ...COLORS.hippocampus,
};

/**
 * Three folds sketched across the cerebellum's visible lower half.
 */
export const FOLIA: string[] = [0.42, 0.58, 0.74].map(f => {
  const y = cb[1] + (cb[3] - cb[1]) * f;
  const inset = 10 + 14 * Math.abs(f - 0.58);
  return `M${(cb[0] + inset).toFixed(1)} ${y.toFixed(1)} Q${((cb[0] + cb[2]) / 2).toFixed(1)} ${(y + 7).toFixed(1)} ${(cb[2] - inset).toFixed(1)} ${(y - 3).toFixed(1)}`;
});

const parcels = art.parcels as Record<string, { x: number; y: number; r: number }>;

/**
 * The hero animation's tau blobs: every cortical parcel at its real projected position, appearing
 * in Braak-stage order, sized by the parcel's real extent.
 */
export const HERO_SPREAD: TauBlob[] = Object.entries(parcels)
  .map(([label, p]) => ({ p, stage: BRAAK_STAGE[label] ?? 6 }))
  .sort((a, b) => a.stage - b.stage || b.p.r - a.p.r)
  .map(({ p, stage }, i) => ({ x: p.x, y: p.y, r: p.r * 1.8, at: Math.min(0.9, ((stage - 1) / 6) * 0.78 + i * 0.012 ) }));

/**
 * Static starting points for each condition's card, read from the scenarios' real seed regions.
 */
export const START_SPOTS: Record<ScenarioId, TauBlob[]> = Object.fromEntries(
  SCENARIOS.map(s => {
    const spots = s.seeds.filter(l => parcels[l]).map(l => ({ x: parcels[l].x, y: parcels[l].y, r: Math.max(26, parcels[l].r * 1.9), at: 0 }));
    if (s.id === 'alzheimers') spots.push({ x: HIPPO_ANCHOR.x, y: HIPPO_ANCHOR.y, r: 30, at: 0 });
    return [s.id, spots];
  }),
) as Record<ScenarioId, TauBlob[]>;
